+import { createEventCard } from './event-card.js';
+
+export function orderByStart(events, project) {
+  return events
+    .map((event, index) => {
+      const value = project(event);
+      return { value, index, time: new Date(event.startsAt).getTime() };
+    })
+    .sort((a, b) => a.time - b.time || a.index - b.index)
+    .map(({ value }) => value);
+}
+
+export function buildAgenda(events) {
+  return orderByStart(events, createEventCard);
+}

